<?php
require __DIR__.'/auth.php';requireAdmin();require dirname(__DIR__).'/includes/bootstrap.php';require dirname(__DIR__).'/includes/listings.php';require dirname(__DIR__).'/Config/blog.php';
$db=adminDb();$errors=[];$edit=filter_var($_GET['edit']??0,FILTER_VALIDATE_INT);$editing=isset($_GET['new'])||$edit>0;
$defaults=['title'=>'','slug'=>'','excerpt'=>'','content'=>'','category'=>'','tags'=>'','author'=>currentUser()['name']?:'Royalmark Estate','type'=>'article','youtube'=>'','youtube_id'=>'','image'=>'','alt'=>'','status'=>'draft','published_at'=>date('Y-m-d\TH:i'),'featured'=>'0','seo_title'=>'','seo_description'=>''];$data=$defaults;
if($edit){$q=$db->prepare('SELECT payload,slug FROM blog_posts WHERE id=?');$q->execute([$edit]);$row=$q->fetch();if(!$row){http_response_code(404);$errors[]='Post not found.';$editing=false;}else{$data=array_merge($defaults,json_decode($row['payload'],true)?:[]);$data['slug']=$row['slug'];}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 adminCsrf();$action=is_string($_POST['action']??null)?$_POST['action']:'';$id=filter_var($_POST['id']??0,FILTER_VALIDATE_INT);$old=null;
 if($id){$q=$db->prepare('SELECT payload FROM blog_posts WHERE id=?');$q->execute([$id]);$stored=$q->fetchColumn();if($stored)$old=json_decode($stored,true);else $errors[]='Post no longer exists.';}
 if($action==='delete'){
  if(!$id)$errors[]='Choose a post to delete.';
  if(!$errors){$q=$db->prepare('DELETE FROM blog_posts WHERE id=?');$q->execute([$id]);blogDeleteImage($old['image']??'');$_SESSION['blog_notice']='Post deleted.';header('Location: ./blog');exit;}
 }elseif($action==='save'){
  $editing=true;$edit=$id;$data=$defaults;
  foreach($defaults as $key=>$value)$data[$key]=is_string($_POST[$key]??null)?trim($_POST[$key]):$value;
  $data['seo_title']=$old['seo_title']??'';$data['seo_description']=$old['seo_description']??'';
  $data['image']=$old['image']??'';$data['youtube_id']='';$data['featured']=($_POST['featured']??'')==='1'?'1':'0';
  foreach(['title'=>180,'slug'=>180,'excerpt'=>500,'content'=>100000,'category'=>100,'tags'=>500,'author'=>100,'youtube'=>500,'alt'=>200,'seo_title'=>180,'seo_description'=>300] as $key=>$max)if(mb_strlen($data[$key])>$max)$errors[]=ucfirst($key).' is too long.';
  if($data['title']===''||$data['author']==='')$errors[]='Title and author are required.';
  if(!in_array($data['type'],['article','video','short'],true)||!in_array($data['status'],['draft','published'],true))$errors[]='Choose a valid post type and status.';
  if($data['type']==='article'&&$data['content']==='')$errors[]='Article content is required.';
  if(in_array($data['type'],['video','short'],true)){ $data['youtube_id']=blogYoutubeId($data['youtube'])??'';if($data['youtube_id']==='')$errors[]='Enter a valid YouTube video or Shorts link.'; }else $data['youtube']='';
  $date=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$data['published_at']);if(!$date||$date->format('Y-m-d\TH:i')!==$data['published_at'])$errors[]='Choose a valid publication date.';
  $slug=strtolower($data['slug']?:$data['title']);$slug=trim(preg_replace('/[^a-z0-9]+/','-',$slug),'-');if($slug==='')$slug='post-'.bin2hex(random_bytes(5));$data['slug']=substr($slug,0,180);
  $upload=$_FILES['image']??null;$newFile=null;
  if($upload&&$upload['error']!==UPLOAD_ERR_NO_FILE){
   if($upload['error']!==UPLOAD_ERR_OK)$errors[]='Image upload failed. Maximum size is 5 MB.';
   else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($upload['tmp_name']);$extension=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';$size=@getimagesize($upload['tmp_name']);if(!$extension||!$size||$upload['size']>5*1024*1024||$size[0]*$size[1]>40000000)$errors[]='Choose a JPEG, PNG or WebP image up to 5 MB and 40 megapixels.';
    elseif(!$errors){$name='blog-'.bin2hex(random_bytes(16)).'.'.$extension;$newFile=dirname(__DIR__).'/assets/uploads/'.$name;if(!move_uploaded_file($upload['tmp_name'],$newFile)){$newFile=null;$errors[]='Could not store the image.';}else $data['image']='./assets/uploads/'.$name;}
   }
  }
  if($data['type']==='article'&&$data['image']==='')$errors[]='Upload a cover image for the article.';
  if(!$errors){try{$payload=json_encode($data,JSON_THROW_ON_ERROR);if($id){$q=$db->prepare('UPDATE blog_posts SET slug=?,payload=? WHERE id=?');$q->execute([$data['slug'],$payload,$id]);}else{$q=$db->prepare('INSERT INTO blog_posts (slug,payload) VALUES (?,?)');$q->execute([$data['slug'],$payload]);}if($newFile&&($old['image']??'')!==$data['image'])blogDeleteImage($old['image']??'');$_SESSION['blog_notice']=$id?'Post updated.':'Post created.';header('Location: ./blog');exit;}catch(PDOException $exception){$errors[]=($exception->errorInfo[1]??0)===1062?'This slug already exists. Choose a different slug.':'Could not save the post. Please try again.';}}
  if($newFile){unlink($newFile);$data['image']=$old['image']??'';}
 }else $errors[]='Invalid action.';
}
$query=is_string($_GET['q']??null)?trim($_GET['q']):'';$filter=is_string($_GET['status']??null)?$_GET['status']:'';$posts=[];
foreach($db->query('SELECT id,payload FROM blog_posts ORDER BY id DESC') as $row){$post=json_decode($row['payload'],true);if(!is_array($post))continue;$post['id']=$row['id'];if(($query===''||mb_stripos($post['title'].' '.$post['category'].' '.$post['author'],$query)!==false)&&($filter===''||$post['status']===$filter))$posts[]=$post;}
$notice=$_SESSION['blog_notice']??'';unset($_SESSION['blog_notice']);$properties=listingData();$view='blog';$title=$editing?($edit?'Edit blog post':'Create blog post'):'Blog';require __DIR__.'/header.php';
?>
<link rel="stylesheet" href="./blog.css?v=1"><script src="./blog.js?v=1" defer></script>
<div class="page-heading"><div><span class="eyebrow">CONTENT MANAGEMENT</span><h1><?= e($title) ?></h1><p>Manage articles, YouTube videos and Shorts. Content is currently managed in the dashboard only.</p></div><a class="primary-button" href="./blog<?= $editing?'':'?new=1' ?>"><?= $editing?'All posts':'+ Create post' ?></a></div>
<?php if($notice): ?><div class="success-note" role="status"><?= e($notice) ?></div><?php endif; ?><?php if($errors): ?><div class="form-error" role="alert"><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if($editing): ?>
<form method="post" enctype="multipart/form-data" class="property-form blog-editor"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)$edit ?>">
<section class="panel form-section"><h2>Post details</h2><div class="form-grid"><?php foreach(['title'=>'Title','slug'=>'Slug (generated if empty)','author'=>'Author','category'=>'Category','tags'=>'Tags (comma separated)','excerpt'=>'Short description'] as $key=>$label): ?><label><?= e($label) ?><input name="<?= $key ?>" value="<?= e($data[$key]) ?>" maxlength="<?= in_array($key,['tags','excerpt'],true)?500:($key==='author'||$key==='category'?100:180) ?>" <?= in_array($key,['title','author'],true)?'required':'' ?>></label><?php endforeach; ?><label>Post type<select name="type" id="blog-type"><?php foreach(['article'=>'Image / Article','video'=>'YouTube Video','short'=>'YouTube Short'] as $value=>$label): ?><option value="<?= $value ?>" <?= $data['type']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><?php foreach(['draft'=>'Draft','published'=>'Published'] as $value=>$label): ?><option value="<?= $value ?>" <?= $data['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Publication date<input type="datetime-local" name="published_at" value="<?= e($data['published_at']) ?>" required></label></div><label>Content / Video description<textarea name="content" rows="12" maxlength="100000"><?= e($data['content']) ?></textarea></label><label class="checkbox-label"><input type="checkbox" name="featured" value="1" <?= $data['featured']==='1'?'checked':'' ?>> Featured post</label></section>
<section class="panel form-section"><h2>Media</h2><div id="blog-youtube-fields"><label>YouTube URL<input type="url" name="youtube" id="blog-youtube" maxlength="500" value="<?= e($data['youtube']) ?>" placeholder="https://www.youtube.com/watch?v=... or /shorts/..."></label><p>Paste a YouTube link. Choose Video for landscape or Short for a vertical preview; no video file upload is needed.</p><iframe id="blog-video-preview" title="YouTube preview" src="about:blank" allow="accelerometer; encrypted-media; gyroscope; picture-in-picture" allowfullscreen hidden></iframe><p id="blog-video-message" role="status"></p></div><label>Cover image (optional for YouTube posts)<input type="file" name="image" id="blog-image" accept="image/jpeg,image/png,image/webp"></label><p>JPEG, PNG or WebP, up to 5 MB. Existing image stays when no new image is selected. YouTube thumbnail is used if a video has no cover image.</p><img id="blog-image-preview" src="<?= e($data['image']?'../'.substr($data['image'],2):'') ?>" alt="Cover preview" <?= !$data['image']?'hidden':'' ?>><label>Image alt text<input name="alt" maxlength="200" value="<?= e($data['alt']) ?>"></label></section>
<div class="form-actions"><a href="./blog">Cancel</a><button class="primary-button" type="submit">Save post</button></div></form>
<?php else: ?>
<section class="panel form-section"><form class="catalog-search blog-search" method="get"><input name="q" value="<?= e($query) ?>" placeholder="Search title, category or author" aria-label="Search posts"><select name="status" aria-label="Filter status"><option value="">All statuses</option><option value="draft" <?= $filter==='draft'?'selected':'' ?>>Draft</option><option value="published" <?= $filter==='published'?'selected':'' ?>>Published</option></select><button class="primary-button">Search</button><a href="./blog">Reset</a></form><p><?= count($posts) ?> posts</p></section>
<div class="blog-admin-grid"><?php foreach($posts as $post): $image=$post['image']?'../'.substr($post['image'],2):(!empty($post['youtube_id'])?'https://i.ytimg.com/vi/'.$post['youtube_id'].'/hqdefault.jpg':''); ?><article class="panel blog-admin-card"><?php if($image): ?><img src="<?= e($image) ?>" alt="<?= e($post['alt']?:$post['title']) ?>" loading="lazy"><?php endif; ?><div><span class="subtle-tag"><?= e(ucfirst($post['status'])) ?> · <?= e(['article'=>'Article','video'=>'YouTube Video','short'=>'YouTube Short'][$post['type']]??'Article') ?></span><h2><?= e($post['title']) ?></h2><p><?= e($post['excerpt']) ?></p><p><?= e($post['author']) ?> · <?= e($post['category']?:'Uncategorized') ?></p><p><?= e(str_replace('T',' ',$post['published_at'])) ?><?= $post['featured']==='1'?' · Featured':'' ?></p><div class="blog-card-actions"><a class="primary-button" href="./blog?edit=<?= $post['id'] ?>">Edit</a><form method="post" class="delete-user-form blog-delete-form" data-title="<?= e($post['title']) ?>"><input type="hidden" name="csrf" value="<?= e(adminToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $post['id'] ?>"><button class="role-button" type="submit">Delete</button></form></div></div></article><?php endforeach; ?></div><?php if(!$posts): ?><section class="panel empty-state">No posts found. Create a post or change your search.</section><?php endif; ?>
<dialog id="blog-delete-modal" class="catalog-modal"><h2>Delete blog post?</h2><p id="blog-delete-name"></p><p>This permanently removes the post.</p><div class="form-actions"><button type="button" class="role-button" data-blog-cancel>Cancel</button><button type="button" class="primary-button" data-blog-confirm>Delete post</button></div></dialog>
<?php endif;require __DIR__.'/footer.php'; ?>
